// BackendHeurMode [BackendHeurMode] is an enumerated type that indicates the operation mode of a [BackendEngineheurDescriptor].
type BackendHeurMode int32

const (
	HeurModeInstant BackendHeurMode = 0
	// HeurModeB: Can utilize the neural net based heuristics to improve generalization performance compared to [HeurModeInstant]. In cases where the neural net is utilized, inference time on the CPU will be increased by 10-100x compared to [HeurModeInstant]. These neural net heuristics are not supported for any of the following cases: Further, the neural net is only enabled on x86 platforms when cuDNN is run on an A100 GPU. In cases where the neural net is not supported, [HeurModeB] will fall back to [HeurModeInstant]. [HeurModeB] will also fall back to [HeurModeInstant] in cases where the overhead of [HeurModeB] is projected to reduce overall network performance.
	HeurModeB BackendHeurMode = 1
	// HeurModeFallback: This heuristic mode is intended to be used for finding fallback options which provide functional support (without any expectation of providing optimal GPU performance).
	HeurModeFallback BackendHeurMode = 2
	HeurModeA        BackendHeurMode = 3
	HeurModesCount   BackendHeurMode = 4
)

